script:
(function (root_element) {
  // Set Month Name for Adherence
  let today = frappe.datetime.now_date();
  let today_date = frappe.datetime.str_to_obj(today);
  let month_name = today_date.toLocaleDateString("en-GB", {
    month: "long",
    year: "numeric",
  });

  let monthEl = root_element.querySelector("#adherence-month-name");
  if (monthEl) {
    monthEl.textContent = month_name;
  }

  // Generate last 6 months options
  function populateMonthOptions() {
    let selectEl = root_element.querySelector("#adherence-month-select");
    if (!selectEl) return;

    let today = frappe.datetime.now_date();
    let today_date = frappe.datetime.str_to_obj(today);

    for (let i = 0; i < 6; i++) {
      let d = new Date(today_date.getFullYear(), today_date.getMonth() - i, 1);
      let month_name = d.toLocaleDateString("en-GB", {
        month: "long",
        year: "numeric",
      });

      let opt = document.createElement("option");
      opt.value = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(
        2,
        "0"
      )}`; // format: 2025-09
      opt.textContent = month_name;

      if (i === 0) opt.selected = true; // current month by default
      selectEl.appendChild(opt);
    }
  }

  function loadAttendanceSummary(monthValue) {
    frappe.call({
      method: "edge.api.workspace.get_attendance_summary",
      args: { month: monthValue },
      callback: function (r) {
        if (r.message) {
          let data = r.message;
          console.log("Attendance summary data:", data);

          let options = {
            chart: {
              type: "donut",
              height: 180,
              width: 400,
            },
            series: [
              data["Present"] || 0,
              data["On Leave"] || 0,
              data["Absent"] || 0,
              data["Half Day"] || 0,
            ],
            labels: [
              `Present (${data["Present"] || 0})`,
              `On Leave (${data["On Leave"] || 0})`,
              `Absent (${data["Absent"] || 0})`,
              `Half Day (${data["Half Day"] || 0})`,
            ],
            colors: ["#00C853", "#00B0FF", "#FF3D00", "#FFC400", "#CFD8DC"],
            legend: {
              position: "right",
              fontSize: "14px",
              markers: { width: 12, height: 12 },
              itemMargin: { horizontal: 10, vertical: 8 },
              formatter: function (seriesName, opts) {
                return seriesName;
              },
            },

            tooltip: { enabled: false },
            dataLabels: { enabled: false },
            plotOptions: {
              pie: {
                donut: {
                  size: "90%",
                  labels: { show: false },
                },
              },
            },
            responsive: [
              {
                breakpoint: 480,
                options: {
                  chart: { width: 250 },
                  legend: { position: "bottom" },
                },
              },
            ],
          };

          let chartContainer = root_element.querySelector("#adherence-chart");
          if (chartContainer) {
            chartContainer.innerHTML = "";
            let chart = new ApexCharts(chartContainer, options);
            chart.render();
            let total =
              (data["Present"] || 0) +
              (data["On Leave"] || 0) +
              (data["Absent"] || 0) +
              (data["Work From Home"] || 0) +
              (data["Half Day"] || 0);

            let centerNumber = chartContainer.parentElement.querySelector(
              ".donut-center .number"
            );
            let centerLabel = chartContainer.parentElement.querySelector(
              ".donut-center .label"
            );

            if (centerNumber) centerNumber.textContent = total;
            if (centerLabel) centerLabel.textContent = "Days";
          } else {
            console.error("❌ No #adherence-chart container found in DOM");
          }
        }
      },
    });
  }

  frappe.after_ajax(() => {
    populateMonthOptions();

    // load current month initially
    let selectEl = root_element.querySelector("#adherence-month-select");
    loadAttendanceSummary(selectEl.value);

    // change event
    selectEl.addEventListener("change", function () {
      loadAttendanceSummary(this.value);
    });

    checkLateArrivalStatus();

    // Optionally refresh every hour
    // setInterval(checkLateArrivalStatus, 3600000);
  });

  // Handle "Add Referral" button click
  let btn_referral = root_element.querySelector("#add-referral-btn");
  if (btn_referral) {
    btn_referral.addEventListener("click", function () {
      let random_id = frappe.utils.get_random(10);
      let docname = `new-employee-referral-${random_id}`;
      let url = `/app/employee-referral/${docname}`;
      window.open(url, "_blank").focus();
    });
  }

  // Handle "New Joinees" button click
  let btn_new_joinees = root_element.querySelector("#new-joinees-btn");
  if (btn_new_joinees) {
    btn_new_joinees.addEventListener("click", function () {
      let selectEl = root_element.querySelector("#adherence-month-select");
      let selectedMonth = selectEl ? selectEl.value : null;

      if (!selectedMonth) {
        frappe.msgprint("Please select a month first.");
        return;
      }

      // Parse the month value (format: 2025-12)
      let [year, month] = selectedMonth.split("-");
      let startDate = `${year}-${month}-01`;

      // Calculate end date (last day of month)
      let endDate = new Date(parseInt(year), parseInt(month), 0);
      let endDateStr = `${year}-${month}-${String(endDate.getDate()).padStart(
        2,
        "0"
      )}`;

      frappe.call({
        method: "edge.api.workspace.get_new_joinees",
        args: {
          start_date: startDate,
          end_date: endDateStr,
        },
        callback: function (r) {
          let html = "";

          if (r.message && r.message.length > 0) {
            html = `
            <style>
              .new-joinees-container { padding: 8px; }
              .employee-card { 
                background: #F8FAFC; 
                border: 1px solid #E2E8F0; 
                border-radius: 6px; 
                padding: 8px; 
                transition: all 0.3s ease; 
                cursor: pointer; 
                height: 100%; 
                margin-bottom: 8px;
              }
              .employee-card:hover { 
                background: #fff; 
                box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06); 
                transform: translateY(-1px); 
                border-color: #2B7FFF; 
              }
              .employee-image-wrapper { flex-shrink: 0; margin-right: 10px; }
              .employee-image { 
                width: 40px; 
                height: 40px; 
                border-radius: 50%; 
                object-fit: cover; 
                border: 2px solid #fff; 
                box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1); 
              }
              .employee-details { flex: 1; }
              .employee-name { 
                font-size: 13px; 
                font-weight: 600; 
                color: #0F172B; 
                margin: 0 0 3px 0; 
              }
              .employee-id, .employee-designation, .employee-department, .employee-joining { 
                font-size: 11px; 
                color: #45556C; 
                margin: 1px 0; 
                display: flex; 
                align-items: center; 
                gap: 3px; 
                line-height: 1.3; 
              }
              .employee-details i { color: #2B7FFF; font-size: 11px; }
            </style>
            <div class="new-joinees-container">
              <div class="row" style="margin: 0 -4px;">
          `;
            r.message.forEach((emp) => {
              let empImage =
                emp.image || "/assets/frappe/images/default-avatar.png";
              html += `
              <div class="col-md-6" style="padding: 0 4px;">
                <div class="employee-card" onclick="window.open('/app/employee/${
                  emp.name
                }', '_blank')">
                  <div style="display: flex; align-items: center;">
                    <div class="employee-image-wrapper">
                      <img src="${empImage}" alt="${
                emp.employee_name || emp.name
              }" class="employee-image">
                    </div>
                    <div class="employee-details">
                      <h6 class="employee-name">${
                        emp.employee_name || emp.name
                      }</h6>
                      <p class="employee-id"><i class="bi bi-person-badge"></i> ${
                        emp.name
                      }</p>
                      <p class="employee-designation"><i class="bi bi-briefcase"></i> ${
                        emp.designation || "N/A"
                      }</p>
                      <p class="employee-department"><i class="bi bi-building"></i> ${
                        emp.department || "N/A"
                      }</p>
                      <p class="employee-joining" style="margin-bottom: 0;"><i class="bi bi-calendar-check"></i> ${frappe.datetime.str_to_user(
                        emp.date_of_joining
                      )}</p>
                    </div>
                  </div>
                </div>
              </div>
            `;
            });
            html += `
              </div>
            </div>
          `;
          } else {
            html = `
            <div style="text-align: center; padding: 40px 0;">
              <i class="bi bi-person-x" style="font-size: 48px; color: #ccc;"></i>
              <p style="margin-top: 16px; color: #6c757d;">No new joinees found for the selected month.</p>
            </div>
          `;
          }

          let d = new frappe.ui.Dialog({
            title: `<i class="bi bi-people-fill"></i> New Joinees - ${
              selectEl.options[selectEl.selectedIndex].text
            }`,
            size: "extra-large",
            primary_action_label: "Close",
            primary_action: () => d.hide(),
          });

          d.$body.html(html);
          d.show();
        },
      });
    });
  }


  // Handle "Training Events" button click
  let btn_training = root_element.querySelector("#training-event-btn");
  if (btn_training) {
    btn_training.addEventListener("click", function () {
      frappe.call({
        method: "frappe.client.get_list",
        args: {
          doctype: "Training Event",
          fields: [
            "name",
            "event_name",
            "start_time",
            "end_time",
            "location",
            "event_status",
            "trainer_name",
          ],
          order_by: "start_time desc",
          limit: 50,
        },
        callback: function (r) {
          let html = "";

          if (r.message && r.message.length > 0) {
            html = `
            <style>
              .training-events-container { padding: 8px; }
              .training-event-card { 
                background: #F8FAFC; 
                border: 1px solid #E2E8F0; 
                border-radius: 6px; 
                padding: 10px; 
                transition: all 0.3s ease; 
                cursor: pointer; 
                height: 100%; 
                margin-bottom: 8px;
              }
              .training-event-card:hover { 
                background: #fff; 
                box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06); 
                transform: translateY(-1px); 
                border-color: #2B7FFF; 
              }
              .event-header { 
                display: flex; 
                justify-content: space-between; 
                align-items: start; 
                border-bottom: 1px solid #E2E8F0; 
                padding-bottom: 6px; 
                margin-bottom: 6px; 
              }
              .event-name { 
                font-size: 12px; 
                font-weight: 600; 
                color: #0F172B; 
                margin: 0; 
                display: flex; 
                align-items: center; 
                gap: 5px; 
                flex: 1; 
                line-height: 1.3; 
              }
              .event-name i { color: #2B7FFF; font-size: 13px; }
              .event-status { 
                padding: 2px 6px; 
                border-radius: 10px; 
                font-size: 10px; 
                font-weight: 500; 
                white-space: nowrap; 
                display: inline-flex; 
                align-items: center; 
                gap: 3px; 
              }
              .status-scheduled { background: #E0F2FE; color: #0369A1; }
              .status-completed { background: #D1FAE5; color: #065F46; }
              .status-cancelled { background: #FEE2E2; color: #991B1B; }
              .status-default { background: #F1F5F9; color: #475569; }
              .event-details { padding-top: 2px; }
              .event-info { 
                font-size: 11px; 
                color: #45556C; 
                margin: 3px 0; 
                display: flex; 
                align-items: center; 
                gap: 5px; 
                line-height: 1.3; 
              }
              .event-info i { font-size: 13px; width: 14px; text-align: center; flex-shrink: 0; }
              .event-info strong { color: #0F172B; min-width: 45px; font-size: 10px; }
            </style>
            <div class="training-events-container">
              <div class="row" style="margin: 0 -4px;">
          `;
            r.message.forEach((event) => {
              let statusClass = "";
              let statusIcon = "";
              switch (event.event_status) {
                case "Scheduled":
                  statusClass = "status-scheduled";
                  statusIcon = "bi-clock";
                  break;
                case "Completed":
                  statusClass = "status-completed";
                  statusIcon = "bi-check-circle";
                  break;
                case "Cancelled":
                  statusClass = "status-cancelled";
                  statusIcon = "bi-x-circle";
                  break;
                default:
                  statusClass = "status-default";
                  statusIcon = "bi-circle";
              }

              html += `
              <div class="col-md-6" style="padding: 0 4px;">
                <div class="training-event-card" onclick="window.open('/app/training-event/${
                  event.name
                }', '_blank')">
                  <div class="event-header">
                    <h6 class="event-name">
                      <i class="bi bi-calendar-event"></i> ${
                        event.event_name || event.name
                      }
                    </h6>
                    <span class="event-status ${statusClass}">
                      <i class="bi ${statusIcon}"></i> ${
                event.event_status || "N/A"
              }
                    </span>
                  </div>
                  <div class="event-details">
                    <p class="event-info">
                      <i class="bi bi-clock-history" style="color: #2B7FFF;"></i>
                      <strong>Start:</strong> ${
                        event.start_time
                          ? frappe.datetime.str_to_user(event.start_time)
                          : "N/A"
                      }
                    </p>
                    <p class="event-info">
                      <i class="bi bi-clock-history" style="color: #dc2626;"></i>
                      <strong>End:</strong> ${
                        event.end_time
                          ? frappe.datetime.str_to_user(event.end_time)
                          : "N/A"
                      }
                    </p>
                    <p class="event-info">
                      <i class="bi bi-geo-alt"></i>
                      <strong>Location:</strong> ${event.location || "N/A"}
                    </p>
                    ${
                      event.trainer_name
                        ? `
                      <p class="event-info" style="margin-bottom: 0;">
                        <i class="bi bi-person-video3"></i>
                        <strong>Trainer:</strong> ${event.trainer_name}
                      </p>
                    `
                        : ""
                    }
                  </div>
                </div>
              </div>
            `;
            });
            html += `
              </div>
            </div>
          `;
          } else {
            html = `
            <div style="text-align: center; padding: 40px 0;">
              <i class="bi bi-calendar-x" style="font-size: 48px; color: #ccc;"></i>
              <p style="margin-top: 16px; color: #6c757d;">No training events found.</p>
            </div>
          `;
          }

          let d = new frappe.ui.Dialog({
            title: '<i class="bi bi-mortarboard-fill"></i> Training Events',
            size: "extra-large",
            primary_action_label: "Close",
            primary_action: () => d.hide(),
          });

          d.$body.html(html);
          d.show();
        },
      });
    });
  }

  // ---------------- Time Utilization ----------------
  let breakIntervals = {};
  let activeBreakType = null;

  function parseServerDatetime(dt) {
    if (!dt) return new Date();
    if (typeof dt === "string") {
      let s = dt.replace(" ", "T");
      s = s.replace(/(\.\d{3})\d+/, "$1");
      return new Date(s);
    }
    return new Date(dt);
  }

  function formatTime(secondsFloat) {
    secondsFloat = Math.max(0, Number(secondsFloat) || 0);
    let totalSeconds = Math.floor(secondsFloat);
    let hh = String(Math.floor(totalSeconds / 3600)).padStart(2, "0");
    let mm = String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0");
    let ss = String(totalSeconds % 60).padStart(2, "0");
    return `${hh}:${mm}:${ss}`;
  }

  function startBreakTimer(breakType, breakId, startTimeFromServer) {
    const rowEl = Array.from(root_element.querySelectorAll(".common-sm-font"))
      .find((el) => el.textContent.trim() === breakType)
      ?.closest(".col-6");
    if (!rowEl) return;

    const switchEl = rowEl.querySelector("input[type=checkbox]");
    if (switchEl) switchEl.dataset.breakId = breakId;
    const timerEl = rowEl.querySelector(".break-timer");
    const startDate = parseServerDatetime(startTimeFromServer);

    if (breakIntervals[breakType]) clearInterval(breakIntervals[breakType]);

    breakIntervals[breakType] = setInterval(() => {
      const diffSec = (Date.now() - startDate.getTime()) / 1000;
      if (timerEl) timerEl.textContent = formatTime(diffSec);
    }, 1000);

    activeBreakType = breakType;
  }

  function stopBreakTimer(breakType, totalSec) {
    if (breakIntervals[breakType]) clearInterval(breakIntervals[breakType]);
    delete breakIntervals[breakType];

    const rowEl = Array.from(root_element.querySelectorAll(".common-sm-font"))
      .find((el) => el.textContent.trim() === breakType)
      ?.closest(".col-6");
    if (!rowEl) return;

    const timerEl = rowEl.querySelector(".break-timer");
    if (timerEl) timerEl.textContent = formatTime(totalSec);

    const switchEl = rowEl.querySelector("input[type=checkbox]");
    if (switchEl) switchEl.dataset.breakId = null;

    if (activeBreakType === breakType) activeBreakType = null;
  }

  function attachSwitchListeners() {
    const switches = root_element.querySelectorAll(
      ".switch input[type=checkbox]"
    );
    switches.forEach((chk) => {
      chk.addEventListener("change", function () {
        const rowEl = this.closest(".p-2.border");
        const breakType = rowEl
          .querySelector(".common-sm-font")
          .textContent.trim();
        const isChecked = this.checked;

        if (isChecked) {
          if (activeBreakType && activeBreakType !== breakType) {
            frappe.msgprint(
              `You already have <b>${activeBreakType}</b> running. Please stop it first.`
            );
            this.checked = false;
            return;
          }

          frappe.call({
            method: "cap_index.api.workspace.get_today_checkin_status",
            callback: (res) => {
              const status = res.message?.status;

              if (!status || status === "NO_CHECKIN") {
                frappe.msgprint(
                  "You must check in today before starting a break."
                );
                chk.checked = false;
                return;
              }

              if (status === "OUT") {
                frappe.msgprint(
                  "Your last action today is a checkout. Cannot start a break."
                );
                chk.checked = false;
                return;
              }

              if (status === "IN") {
                frappe.confirm(
                  `Are You Sure to Turn <b>${breakType}</b> Timer On?`,
                  () => {
                    frappe.call({
                      method: "edge.api.workspace.start_break",
                      args: { break_type: breakType },
                      callback: (r) => {
                        if (r.message && r.message.success) {
                          frappe.show_alert({
                            message: `${breakType} started`,
                            indicator: "green",
                          });
                          startBreakTimer(
                            breakType,
                            r.message.break_id,
                            r.message.start_time
                          );
                        } else {
                          frappe.msgprint(
                            r.message?.message || "Error starting break"
                          );
                          chk.checked = false;
                        }
                      },
                    });
                  },
                  () => {
                    chk.checked = false;
                  }
                );
              }
            },
          });
        } else {
          const breakId = chk.dataset.breakId;
          if (!breakId) {
            chk.checked = false;
            return;
          }

          frappe.call({
            method: "edge.api.workspace.stop_break",
            args: { break_id: breakId },
            callback: (r) => {
              if (r.message?.success) {
                frappe.show_alert({
                  message: `${breakType} stopped`,
                  indicator: "orange",
                });
                stopBreakTimer(breakType, r.message.total_duration || 0);
              } else {
                frappe.msgprint(r.message?.message || "Error stopping break");
              }
            },
          });
        }
      });
    });
  }

  function initializeUserInfo() {
    const userTimeZone = frappe.sys_defaults.time_zone || "UTC";

    console.log("User Timezone Retrieved:", userTimeZone);

    // Last Logged
    frappe.call({
      method: "frappe.client.get_value",
      args: {
        doctype: "User",
        filters: { name: frappe.session.user },
        fieldname: "last_login",
      },
      callback: function (r) {
        if (r.message && r.message.last_login) {
          let utcDate = new Date(r.message.last_login);
          let localDateStr = utcDate.toLocaleString("en-GB", {
            timeZone: frappe.sys_defaults.time_zone || "UTC",
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            second: "2-digit",
            hour12: false,
          });
          let [date_str, time_str] = localDateStr.split(", ");
          const timeEl = root_element.querySelector("#last_logged");
          if (timeEl) timeEl.textContent = time_str;
          const dateEl = root_element.querySelector("#last_logged_date");
          if (dateEl) dateEl.textContent = date_str;
        }
      },
    });

    // EST Clock
    setInterval(() => {
      let now = new Date();
      let est_time = now.toLocaleString("en-GB", {
        timeZone: "America/New_York",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        hour12: false,
      });
      const el = root_element.querySelector("#est_time");
      if (el) el.textContent = est_time;
    }, 1000);

    // User's Local Clock
    setInterval(() => {
      let now = new Date();
      let local_time = now.toLocaleString("en-GB", {
        timeZone: userTimeZone,
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        hour12: false,
      });

      const el = root_element.querySelector("#local_time");
      if (el) el.textContent = local_time;
    }, 1000);

    // Today's Date
    let date_str_in_tz = new Date().toLocaleString("en-US", {
      timeZone: userTimeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });

    let today_date = new Date(date_str_in_tz);

    let formatted_date = today_date.toLocaleDateString("en-GB", {
      day: "2-digit",
      month: "long",
      year: "numeric",
    });

    const el = root_element.querySelector("#today_date");
    if (el) el.textContent = formatted_date;
  }

  function checkLateArrivalStatus() {
    const currentDate = new Date();
    const month = `${currentDate.getFullYear()}-${String(
      currentDate.getMonth() + 1
    ).padStart(2, "0")}`;

    frappe.call({
      method: "edge.api.workspace.get_late_arrival_status",
      args: { month: month },
      callback: function (r) {
        if (r.message && r.message.show_warning) {
          const data = r.message;
          const warningEl = root_element.querySelector("#late-arrival-warning");
          const messageEl = root_element.querySelector("#late-warning-message");
          const progressFill = root_element.querySelector(
            "#late-progress-fill"
          );
          const timeUsedEl = root_element.querySelector("#late-time-used");
          const timeAllowedEl =
            root_element.querySelector("#late-time-allowed");

          if (warningEl && messageEl && progressFill) {
            // Calculate percentage
            const percentage = Math.min(
              (data.total_late_minutes / data.allowed_minutes) * 100,
              100
            );

            // Set warning level class
            warningEl.className = warningEl.className.replace(
              /warning-level-\w+/g,
              ""
            );
            if (data.warning_level === "critical") {
              warningEl.classList.add("warning-level-critical");
              messageEl.textContent = data.exceeded
                ? `You have exceeded your monthly late arrival limit by ${data.excess_minutes} minutes.`
                : `You have reached your monthly late arrival limit.`;
            } else if (data.warning_level === "high") {
              warningEl.classList.add("warning-level-high");
              messageEl.textContent = `You are approaching your late arrival limit. Only ${data.remaining_minutes} minutes remaining.`;
            } else {
              warningEl.classList.add("warning-level-medium");
              messageEl.textContent = `You have ${data.remaining_minutes} minutes remaining in your late arrival allowance.`;
            }

            // Update progress bar
            progressFill.style.width = `${percentage}%`;

            // Update time display
            timeUsedEl.textContent = data.total_late_minutes;
            timeAllowedEl.textContent = data.allowed_minutes;

            // Show warning
            warningEl.style.display = "block";
          }
        } else {
          // Hide warning if not needed
          const warningEl = root_element.querySelector("#late-arrival-warning");
          if (warningEl) {
            warningEl.style.display = "none";
          }
        }
      },
    });
  }

  // Initialize
  attachSwitchListeners();
  initializeUserInfo();
})(root_element);

